    const items = itemsFromMenu.length > 0 ? itemsFromMenu : [
        { id: 'prep_rice', name: 'Steamed Basmati Rice', icon: '🍚' },
        { id: 'prep_sauce_red', name: 'Tomato/Curry Base', icon: '🥫' },
        { id: 'prep_veg', name: 'Roasted Seasonal Veg', icon: '🥦' }
    ];

    items.forEach(item => {
