            ${isDone ? '<div class="absolute -top-1 -right-1 bg-emerald-500 rounded-full p-2 text-white shadow-2xl ring-4 ring-slate-900 z-10"><svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="5" d="M5 13l4 4L19 7"></path></svg></div>' : ''}
            <div class="mb-3 h-14 w-14 rounded-2xl flex items-center justify-center text-2xl bg-emerald-600/10 border border-emerald-500/20 shadow-inner group-hover:bg-emerald-600/20 transition-all">${item.icon || '🥘'}</div>
