    DOMElements.dishCardContainer.innerHTML = `
        <div class="bg-slate-800/80 rounded-[2.5rem] sm:rounded-[4.5rem] shadow-2xl overflow-hidden border border-slate-700/50 backdrop-blur-3xl animate-in zoom-in-95 duration-500">
            <div class="px-8 py-10 sm:px-14 sm:py-12 bg-emerald-600/20 border-b border-white/5">
                <div class="flex items-center gap-6 mb-4">
                    <div class="h-16 w-16 sm:h-20 sm:w-20 rounded-[1.5rem] sm:rounded-[2.5rem] bg-emerald-600 flex items-center justify-center text-3xl sm:text-4xl shadow-2xl">${item.icon || '🥘'}</div>
