    DOMElements.dishCardContainer.querySelector('#edit-btn').onclick = () => setFormDisabled(false);
    form.onsubmit = (e) => {
        e.preventDefault(); const fd = new FormData(e.target);
        const logData = { id: item.id, name: item.name, temperature: fd.get('temperature'), comment: fd.get('comment'), image: e.target.dataset.capturedImage || null, timestamp: new Date().toISOString() };
        set(ref(database, `prep-checks/${state.selectedDate}/${item.id}`), logData).then(() => showView('prep'));
    };
    setFormDisabled(!!saved);
    renderCameraCapture({ dishName: item.name }, saved?.image);
