    let activeStageId = targetStageId || state.activePrepStage;
    if (!activeStageId) {
        const firstIncomplete = PREP_STAGES.find(s => !stagesData[s.id]);
        activeStageId = firstIncomplete ? firstIncomplete.id : PREP_STAGES[0].id;
    }
    state.activePrepStage = activeStageId; // Persist selection while in view

    const currentStageData = stagesData[activeStageId] || { temperature: '', comment: '' };
    const activeStageDef = PREP_STAGES.find(s => s.id === activeStageId);

