        const isDone = !!stagesData[stage.id];
        const isActive = stage.id === activeStageId;
        const baseClass = "flex-1 py-4 text-[10px] sm:text-[11px] font-black uppercase tracking-widest transition-all rounded-xl border";
        const activeClass = "bg-emerald-600 text-white border-emerald-500 shadow-lg shadow-emerald-500/20";
