        const pendingClass = "bg-slate-900/50 text-slate-500 border-slate-800 hover:text-slate-300";

        let stateClass = isActive ? activeClass : (isDone ? doneClass : pendingClass);

        return `<button type="button" onclick="window.renderPrepCard('${stage.id}')" class="${baseClass} ${stateClass} flex flex-col items-center gap-1">
            <span>${stage.short}</span>
            ${isDone ? '<span class="text-[8px] opacity-70">✔ Done</span>' : ''}
