    DOMElements.dishCardContainer.innerHTML = `
        <div class="bg-slate-800/80 rounded-[2.5rem] sm:rounded-[4.5rem] shadow-2xl overflow-hidden border border-slate-700/50 backdrop-blur-3xl animate-in zoom-in-95 duration-500">
            <!-- Header -->
            <div class="px-8 py-8 sm:px-14 sm:py-10 bg-emerald-600/20 border-b border-white/5">
                <div class="flex items-center gap-6 mb-2">
                    <div class="h-14 w-14 sm:h-16 sm:w-16 rounded-[1.5rem] bg-emerald-600 flex items-center justify-center text-3xl shadow-2xl">${item.icon || '🥘'}</div>
                    <div>
