                <div class="flex items-center justify-between">
                    <h4 class="text-xl font-black text-white italic">${activeStageDef.label}</h4>
                    ${currentStageData.timestamp ? `<span class="text-[10px] font-mono text-slate-500">${new Date(currentStageData.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>` : ''}
                </div>

                <div id="camera-container" class="space-y-4"></div>

