                    <label class="block">
                        <span class="text-[10px] font-black text-emerald-400 uppercase tracking-[0.4em] pl-6 mb-4 block">Temperature (°C)</span>
                        <input type="number" inputmode="decimal" step="any" name="temperature" value="${currentStageData.temperature}" placeholder="--" class="block w-full px-6 py-8 sm:px-10 sm:py-12 bg-slate-950/80 border border-emerald-500/30 rounded-[2.5rem] sm:rounded-[4rem] text-6xl sm:text-8xl text-emerald-400 font-mono font-black focus:border-emerald-500 outline-none transition-all shadow-inner text-center leading-none">
