    };

    DOMElements.dishCardContainer.querySelector('#edit-btn').onclick = () => setFormDisabled(false);

    form.onsubmit = (e) => {
        e.preventDefault(); 
        const fd = new FormData(e.target);

        // Data for this specific stage
        const stageData = {
            temperature: fd.get('temperature'),
            image: e.target.dataset.capturedImage || currentStageData.image || null,
