    onValue(ref(database, `menus/${weekId}`), (snapshot) => { 
        state.menu = snapshot.val() || null; 
        state.isMenuLoading = false; 
        renderApp(); 
        if(state.currentView === 'prep') renderPrepView(); 
        if(state.currentView === 'audit') window.renderAuditDishLibrary();
    }); 
}

