            } else {
                // Dish is in menu but has no history in Firebase
                activeDishes.push({
                    name: menuDish.dishName,
                    checks: [],
                    scores: [],
                    isActive: true,
                    isNew: true
                });
            }
        });
    }

    const archivedDishes = [];
    Object.keys(dishStats).forEach(key => {
        if (!usedStatsKeys.has(key)) {
            archivedDishes.push({
                ...dishStats[key],
                isActive: false
